// Über den Namen, nicht über $input: der Drive-Baustein davor ersetzt das Item
const rein = $('Offene Punkte sammeln').first().json;
const d = rein.umschlag?.lieferung?.dateien || [];
if (!d.length) throw new Error('Keine Dateien im Umschlag (BC3-70 Dateien auspacken). Liefen BC3-40 und BC3-50 durch?');
return d.map(x => ({ json: x }));

// Macht aus jeder Datei im Umschlag eine hochladbare Datei (JSON oder Text),
// Hilfsfelder mit _ fallen weg. Dateiname: <art>_<KP>_<projekt>.<endung>
const items = $input.all();
const ausgabe = [];

const NAMEN = {
  tickets: 'ticket_set.json',
  blueprint: 'blueprint.json',
  architecture: 'architecture.md',
  openapi: 'openapi.yaml',
  'compliance-audit': 'compliance-audit.json',
  'offene-punkte': 'offene-punkte.json',
};

for (const item of items) {
  const daten = item.json;
  const art = daten._datei || 'tickets';
  const endung = daten._endung || 'json';
  const rein70 = $('Offene Punkte sammeln').first().json;
  const kpRoh = rein70.umschlag?.konzept?.kp_id || null;
  // Die kleingeschriebene KP-Kennung ist kein Projektname
  const echt = x => x && (!kpRoh || String(x).toLowerCase() !== String(kpRoh).toLowerCase());
  const projekt = [daten.projekt_kurzname,
                   rein70.umschlag?.aggregat?.projekt_kurzname,
                   ...(rein70.umschlag?.lieferung?.dateien || []).map(d => d.projekt_kurzname)]
    .find(echt) || 'lieferung';
  // Kennzeichen vor die Endung, damit sich Lieferungen unterscheiden
  const kp = daten.konzept_ref?.kp_id
    || rein70.umschlag?.konzept?.kp_id
    || null;
  const doppelt = kp && projekt.toLowerCase() === String(kp).toLowerCase();
  const kennzeichen = [kp, doppelt ? null : projekt].filter(Boolean).join('_');

  let text;
  let mime;

  // Alles, was nicht JSON ist, liegt fertig als Text im Feld inhalt.
  const MIME = { md: 'text/markdown', yaml: 'application/yaml',
                 yml: 'application/yaml', txt: 'text/plain', csv: 'text/csv' };
  if (endung !== 'json') {
    text = String(daten.inhalt ?? '');
    mime = MIME[endung] || 'text/plain';
    if (!text) {
      throw new Error(
        `Die Datei "${art}.${endung}" hat keinen Inhalt. ` +
        'Bei allem außer JSON muss der Text im Feld "inhalt" stehen (BC3-70 Upload vorbereiten).'
      );
    }
  } else {
    // Hilfsfelder (_datei, _endung, _statistik ...) entfernen
    const inhalt = {};
    for (const [k, v] of Object.entries(daten)) {
      if (!k.startsWith('_')) inhalt[k] = v;
    }
    text = JSON.stringify(inhalt, null, 2);
    mime = 'application/json';
  }
  const roh = NAMEN[art] || `${art}.${endung}`;
  const punkt = roh.lastIndexOf('.');
  const dateiname = kennzeichen && punkt > 0
    ? `${roh.slice(0, punkt)}_${kennzeichen}${roh.slice(punkt)}`
    : roh;

  ausgabe.push({
    json: {
      filename: dateiname,
      art: art,
      groesse_bytes: Buffer.byteLength(text, 'utf-8'),
      // Kennzahlen nur beim Ticket-Set vorhanden
      anzahl_epics: daten._statistik?.anzahl_epics,
      anzahl_stories: daten._statistik?.anzahl_stories,
      ampel: daten._statistik?.ampel,
    },
    binary: {
      data: {
        data: Buffer.from(text, 'utf-8').toString('base64'),
        mimeType: mime,
        fileName: dateiname,
      },
    },
  });
}

return ausgabe;

// Hält fest, welche Dateien wo liegen (Kennung und Name), oder warum die Ablage scheiterte.
const rein = $('Offene Punkte sammeln').first().json;
const u = rein.umschlag || {};
// Der Ordner der Lieferung, nicht _vorschau; scheiterte das Anlegen, bleibt _vorschau
let ordner = $('Ordnername bestimmen').first().json.eltern;
try { ordner = $('Lieferungsordner anlegen').first().json.id || ordner; } catch (e) { /* _vorschau */ }

let fehler = null;
try {
  const g = $('Ablage gescheitert').first().json;
  if (g && g.ablage_gescheitert) fehler = g;
} catch (e) { fehler = null; }

let abgelegt = [];
if (!fehler) {
  try {
    abgelegt = $('Dateien in den Lieferungsordner legen').all()
      .map(i => ({ id: i.json.id, name: i.json.name }))
      .filter(x => x.id);
  } catch (e) { abgelegt = []; }
}

const soll = (u.lieferung?.dateien || []).length;
const befunde = [];
if (fehler) {
  befunde.push(`Ablage in Google Drive gescheitert: ${fehler.ablage_meldung}`);
  befunde.push(`Die ${fehler.versuchte_dateien.length} Dateien stehen im Umschlag `
    + `(${fehler.versuchte_dateien.join(', ')}), BC3-70 lässt sich mit diesem Umschlag wiederholen.`);
} else if (!abgelegt.length) {
  befunde.push('Google Drive hat keine Dateikennungen zurückgegeben.');
} else if (abgelegt.length !== soll) {
  befunde.push(`Nur ${abgelegt.length} von ${soll} Dateien abgelegt.`);
}

return [{
  json: {
    lauf_id: rein.lauf_id,
    umschlag: {
      ...u,
      lieferung: { ...(u.lieferung || {}), abgelegt, ordner,
                   ablage_gescheitert: !!fehler },
      protokoll: [...(u.protokoll || []), {
        stufe: 'BC3-70 Ausliefern',
        zeitpunkt: new Date().toISOString(),
        status: fehler ? 'mit Fehler' : (befunde.length ? 'mit Befund' : 'ok'),
        ablage: fehler ? 'nicht abgelegt' : '_vorschau',
        dateien: fehler ? fehler.versuchte_dateien : abgelegt.map(x => x.name),
        befunde,
      }],
    },
  },
}];

// Google Drive hat Ordner oder Dateien nicht angenommen. Der Lauf geht weiter,
// die Inhalte stehen im Umschlag, BC3-70 lässt sich mit demselben Umschlag wiederholen.
const q = $('Vom Orchestrator aufgerufen').first().json;
const meldung = String(
  $json.error?.message || $json.message ||
  (typeof $json.error === 'string' ? $json.error : '') || 'ohne Angabe'
).split('\n')[0].slice(0, 300);

// Scheiterte schon der Ordner, ist "Upload vorbereiten" nie gelaufen, dann gilt die Liste im Umschlag
let versucht = [];
try { versucht = $('Upload vorbereiten').all().map(i => i.json.filename).filter(Boolean); }
catch (e) { versucht = []; }
if (!versucht.length) {
  try {
    versucht = ($('Offene Punkte sammeln').first().json.umschlag?.lieferung?.dateien || [])
      .map(d => `${d._datei}.${d._endung || 'json'}`);
  } catch (e) { versucht = []; }
}

return [{
  json: {
    ablage_gescheitert: true,
    ablage_meldung: meldung,
    versuchte_dateien: versucht,
    lauf_id: q.lauf_id,
  },
}];

// Ein Ordner je Lieferung, benannt nach der lieferung_id aus BC3-40.
// Der Elternordner kommt aus dem Lauf (BC3-00 "Lauf einstellen"), nicht aus dem Code.
const rein = $input.first().json;
const u = rein.umschlag || {};
const id = u.lieferung?.lieferung_id;
const eltern = u.lauf?.ablage_ordner;

if (!id) throw new Error('Keine lieferung_id im Umschlag (BC3-70 Ordnername bestimmen). Lief BC3-40 durch?');
if (!eltern) throw new Error('Kein Ablageordner im Lauf (umschlag.lauf.ablage_ordner), in BC3-00 "Lauf einstellen" eintragen');

return [{ json: { ...rein, ordnername: id, eltern } }];

// Sammelt, was zur Lieferung noch offen ist und von wem, als offene-punkte.json.
// Die Datei entsteht immer, auch leer. Jeder Eintrag trägt eine Begründung.
const rein = $input.first().json;
const u = rein.umschlag || {};
const dateien = u.lieferung?.dateien || [];
const audit = dateien.find(d => String(d._datei || '').startsWith('compliance')) || {};

// --- 1. Pflichten, die nicht BC4 baut --------------------------------------
const MASSNAHME_TEXT = {
  mensch_prueft: 'eine menschliche Prüfung an der Stelle, an der die Daten die Entscheidung beeinflussen',
  pseudonymisieren: 'Kontaktdaten vor dem Modellaufruf durch eine Kennung ersetzen und danach zurücksetzen',
  eu_modell: 'ein in der EU betriebenes Modell verwenden',
  feld_weglassen: 'das Feld gar nicht erst mitgeben, weil der Schritt es nicht braucht',
  protokollieren: 'den Vorgang mit Zeitstempel und handelnder Person protokollieren',
  hinweis_geben: 'einen Hinweis auf die automatisierte Erstellung mitgeben',
  frist_vereinbaren: 'eine Frist vereinbaren und schriftlich festhalten',
  andere_bauweise: 'eine andere Bauweise, die vorgesehene ist nach Art. 5 KI-VO oder Art. 9 bzw. 22 DSGVO nicht zulässig; die zulässige steht im Befund',
};

const nachAdressat = audit.pflichten_nach_adressat || {};
const pflichtText = new Map((audit.pflichten || []).map(x => [x.id, x]));
const pflichten = [];
for (const art of ['organisation', 'plattform', 'ohne_angabe']) {
  for (const id of (nachAdressat[art] || [])) {
    const pf = pflichtText.get(id) || {};
    pflichten.push({
      art: 'pflicht',
      titel: String(pf.text || id),
      adressat: art,
      tag: pf.tag || null,
      massnahme: pf.massnahme || null,
      datenkategorie: pf.datenkategorie || null,
      stelle: pf.stelle || null,
      begruendung: (pf.massnahme
        ? `Einzubauen: ${MASSNAHME_TEXT[pf.massnahme] || pf.massnahme}`
          + (pf.stelle ? ` bei "${pf.stelle}".` : '.') + ' '
        : '')
        + (art === 'plattform'
        ? 'Zugewiesen an eine zentrale Vorkehrung (Plattform), nicht an BC4. Wer sie übernimmt, ist offen.'
        : art === 'ohne_angabe'
          ? 'Der Compliance-Befund nennt keinen Adressaten. Vor der Freigabe zuordnen.'
          : 'Braucht einen Menschen, eine Frist oder eine Vereinbarung; BC4 baut '
            + 'sie nicht, aber sie ist damit nicht erledigt.'),
      quelle: 'BC3-30 Compliance',
    });
  }
}

// --- 2. Pflichten, die eine Story werden sollten, aber keine haben ----------
const ohne_story = (audit.pflichten_ohne_story || []).map(x => ({
  art: 'pflicht_ohne_story',
  titel: String(x.text || x.id),
  adressat: 'bc3',
  tag: x.tag || null,
  begruendung: 'Der Compliance-Befund hält diese Pflicht für baubar, hat aber keine '
    + 'Story dazu geliefert. BC3 muss nachfordern; erfunden wird sie nicht.',
  quelle: 'BC3-40 Abgleich Pflichten gegen Stories',
}));

// --- 3. Annahmen aus Verneinungen im Konzept --------------------------------
// BC3 schreibt keine Auflage, wenn das Konzept etwas ausschließt. Das wird mitgeliefert.
const dat = u.aggregat?.datenarten || {};
const trag = u.aggregat?.tragweite || {};
const annahmen = [
  ...(dat.ausdruecklich_ausgeschlossen || []).map(x => ({
    art: 'annahme',
    titel: `Angenommen: ${x.art} kommt im Prozess nicht vor`,
    adressat: 'bc2_und_bc4',
    begruendung: `BC3 hat dazu keine Auflage geschrieben, weil das Konzept es `
      + `ausschließt: "${x.beleg}" Wäre die Datenart doch betroffen, fehlt eine `
      + `Auflage der Stufe ${x.stufe}. Wer diesen Satz im Konzept ändert, ändert `
      + `damit die Rechtslage dieser Lieferung.`,
    beleg: x.beleg,
    quelle: 'BC3-20 Datenarten, Verneinung erkannt',
  })),
  ...(trag.ausdruecklich_ausgeschlossen || []).map(x => ({
    art: 'annahme',
    titel: `Angenommen: der Prozess entscheidet nicht über ${x.art.toLowerCase()}`,
    adressat: 'bc2_und_bc4',
    begruendung: `BC3 hat keinen Aufsichtspunkt dafür verlangt, weil das Konzept es `
      + `ausschließt: "${x.beleg}" Trifft das Zielsystem diese Entscheidung doch, `
      + `greift ${x.anhang} und es fehlt die menschliche Entscheidung an der Stelle.`,
    beleg: x.beleg,
    quelle: 'BC3-20 Tragweite, Verneinung erkannt',
  })),
];

// --- 4. Messverfahren, die das Konzept nicht nennt (seit 22.10.2026) --------
// Kein offener Punkt an Gate 2, sondern eine Rückmeldung an BC2 (Entscheidung Svetlana).
// BC3 gibt die Stories unverändert weiter und erfindet kein Messverfahren.
const tickets = dateien.find(d => d._datei === 'tickets') || {};
const fehltMess = m => !m || /^offen:/i.test(String(m));
const ohneMess = (tickets.epics || []).flatMap(e => (e.stories || [])
  .filter(s => (s.akzeptanzkriterien || []).some(k => fehltMess(k.messverfahren)))
  .map(s => ({ story_id: s.story_id, titel: s.titel })));
const messverfahren = ohneMess.length ? [{
  art: 'messverfahren_fehlt',
  titel: `${ohneMess.length} Stories ohne Messverfahren`,
  adressat: 'bc2',
  begruendung: 'Das Konzept nennt zu diesen Kriterien kein Messverfahren. BC3 gibt die Stories '
    + 'unverändert weiter und erfindet keins. BC4 kann sie bauen, aber nicht nachweisen, dass sie '
    + 'erfüllt sind. Wie BC2 das erfährt und nachliefert, ist mit dem Team zu klären.',
  stories: ohneMess,
  quelle: 'BC3-20 Kriterien, Abgleich mit dem Konzept',
}] : [];

const alle = [...pflichten, ...ohne_story, ...annahmen, ...messverfahren];

const datei = {
  _datei: 'offene-punkte',
  _endung: 'json',
  projekt_kurzname: u.lieferung?.projekt_kurzname
    || (u.konzept?.kp_id || 'bc3').toLowerCase(),
  lieferung_id: u.lieferung?.lieferung_id || null,
  erzeugt_am: new Date().toISOString(),
  hinweis: 'Was zu dieser Lieferung noch offen ist und von wem. Von BC3 erzeugt, '
    + 'nicht von Hand gepflegt. Jeder Eintrag trägt eine Begründung.',
  anzahl: alle.length,
  nach_adressat: alle.reduce((acc, x) => {
    acc[x.adressat] = (acc[x.adressat] || 0) + 1;
    return acc;
  }, {}),
  punkte: alle,
};

return [{
  json: {
    lauf_id: rein.lauf_id,
    umschlag: {
      ...u,
      lieferung: { ...(u.lieferung || {}), dateien: [...dateien, datei] },
      offene_punkte: { anzahl: alle.length, nach_adressat: datei.nach_adressat },
      protokoll: [...(u.protokoll || []), {
        stufe: 'BC3-70 Offene Punkte sammeln',
        zeitpunkt: new Date().toISOString(),
        status: 'ok',
        umfang: datei.nach_adressat,
        befunde: alle.length
          ? [`${alle.length} offene Punkte werden mitgeliefert: `
             + Object.entries(datei.nach_adressat).map(([a, n]) => `${n} an ${a}`).join(', ')
             + '. Jeder mit Begründung.']
          : ['Keine offenen Punkte.'],
      }],
    },
  },
}];
